template:
@php
    // A row without a number has nothing to count. "3 000" and "3,000" are three thousand; "4,9" is four point nine.
    $shown = [];
    foreach (is_array($numbers) ? $numbers : [] as $item) {
        if (! is_array($item)) {
            continue;
        }
        $raw = preg_replace('/[\s\x{00A0}\x{202F}]/u', '', wx_text($item['value'] ?? null)->plain());
        $raw = preg_match('/^-?\d{1,3}(,\d{3})+(\.\d+)?$/', $raw) === 1 ? str_replace(',', '', $raw) : str_replace(',', '.', $raw);
        if (! is_numeric($raw)) {
            continue;
        }
        $shown[] = [
            'value' => $raw,
            'prefix' => wx_text($item['prefix'] ?? null)->plain(),
            'suffix' => wx_text($item['suffix'] ?? null)->plain(),
            'label' => $item['label'] ?? null,
        ];
    }
@endphp
@if ($shown)
<section class="b-counters" data-wx-block="counters">
    @if ($heading)
        <h2 class="b-counters__heading">{{ $heading }}</h2>
    @endif
    <ul class="b-counters__list" role="list">
        @foreach ($shown as $item)
            <li class="b-counters__item">
                <x-webx-counter class="b-counters__number" :value="$item['value']" :prefix="$item['prefix']" :suffix="$item['suffix']" />
                @if ($item['label'])
                    <span class="b-counters__label">{{ $item['label'] }}</span>
                @endif
            </li>
        @endforeach
    </ul>
</section>
@endif

styles:
.b-counters {
    container-type: inline-size;
}

.b-counters__heading {
    margin: 0 0 1em;
    text-align: center;
}

/* As many in a row as fit at ten letters each: four on a desktop, two on a phone. */
.b-counters__list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 10em), 1fr));
    gap: 1.5em 1em;
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-counters__item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25em;
    margin: 0;
    text-align: center;
}

.b-counters__number {
    font-size: 2.5em;
    font-weight: 700;
    line-height: 1.1;
}

.b-counters__label {
    font-size: 0.9375em;
    opacity: 0.75;
}

@container (max-width: 22em) {
    .b-counters__list {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .b-counters__number {
        font-size: 2em;
    }
}
